-- New tables ported from the legacy reference scripts: a generic
-- Attachment store, and three SAP-integration sync-log tables
-- (MasterSync, SAPSync, StockSync) kept separate per instruction even
-- though they are structurally identical in the original design.

CREATE TABLE "Attachment" (
    "DocEntry" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" TEXT NOT NULL,
    "Description" TEXT,
    "CreateDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdateDate" TIMESTAMP(3) NOT NULL,
    "CreatedBy" TEXT,
    "UpdatedBy" TEXT,

    CONSTRAINT "Attachment_pkey" PRIMARY KEY ("DocEntry")
);

CREATE TABLE "AttachmentFile" (
    "DocEntry" INTEGER NOT NULL,
    "LineId" INTEGER NOT NULL,
    "FileName" TEXT NOT NULL,
    "FilePath" TEXT,
    "ContentType" TEXT,
    "FileSize" BIGINT,
    "UploadedBy" TEXT,
    "UploadedDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "AttachmentFile_pkey" PRIMARY KEY ("DocEntry","LineId")
);

CREATE INDEX "Attachment_TenantId_idx" ON "Attachment"("TenantId");

ALTER TABLE "Attachment" ADD CONSTRAINT "Attachment_TenantId_fkey" FOREIGN KEY ("TenantId") REFERENCES "Tenant"("Id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "AttachmentFile" ADD CONSTRAINT "AttachmentFile_DocEntry_fkey" FOREIGN KEY ("DocEntry") REFERENCES "Attachment"("DocEntry") ON DELETE CASCADE ON UPDATE CASCADE;

CREATE TABLE "MasterSync" (
    "DocEntry" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" TEXT NOT NULL,
    "DocNum" TEXT,
    "DocDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "SyncType" TEXT NOT NULL DEFAULT 'Master',
    "SyncObject" TEXT,
    "Direction" TEXT NOT NULL DEFAULT 'POS to SAP',
    "OutletId" TEXT,
    "StartTime" TIMESTAMP(3),
    "EndTime" TIMESTAMP(3),
    "TotalRecords" INTEGER NOT NULL DEFAULT 0,
    "SuccessRecords" INTEGER NOT NULL DEFAULT 0,
    "FailedRecords" INTEGER NOT NULL DEFAULT 0,
    "PendingRecords" INTEGER NOT NULL DEFAULT 0,
    "ErrorMessage" TEXT,
    "RequestedBy" TEXT,
    "Status" TEXT NOT NULL DEFAULT 'Pending',
    "DocStatus" TEXT NOT NULL DEFAULT 'O',
    "Canceled" BOOLEAN NOT NULL DEFAULT false,
    "SapRef" TEXT,
    "SapSyncStatus" TEXT NOT NULL DEFAULT 'Pending',
    "SapSyncDate" TIMESTAMP(3),
    "CreateDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdateDate" TIMESTAMP(3) NOT NULL,
    "CreatedBy" TEXT,
    "UpdatedBy" TEXT,

    CONSTRAINT "MasterSync_pkey" PRIMARY KEY ("DocEntry")
);

CREATE TABLE "MasterSyncLine" (
    "DocEntry" INTEGER NOT NULL,
    "LineId" INTEGER NOT NULL,
    "ObjectType" TEXT,
    "ObjectKey" TEXT,
    "SapDocEntry" TEXT,
    "SyncStatus" TEXT,
    "ErrorMessage" TEXT,
    "SyncDate" TIMESTAMP(3),

    CONSTRAINT "MasterSyncLine_pkey" PRIMARY KEY ("DocEntry","LineId")
);

CREATE UNIQUE INDEX "MasterSync_TenantId_DocNum_key" ON "MasterSync"("TenantId", "DocNum");
CREATE INDEX "MasterSync_TenantId_DocDate_idx" ON "MasterSync"("TenantId", "DocDate");

ALTER TABLE "MasterSync" ADD CONSTRAINT "MasterSync_TenantId_fkey" FOREIGN KEY ("TenantId") REFERENCES "Tenant"("Id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "MasterSync" ADD CONSTRAINT "MasterSync_OutletId_fkey" FOREIGN KEY ("OutletId") REFERENCES "Outlet"("Id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "MasterSyncLine" ADD CONSTRAINT "MasterSyncLine_DocEntry_fkey" FOREIGN KEY ("DocEntry") REFERENCES "MasterSync"("DocEntry") ON DELETE CASCADE ON UPDATE CASCADE;

CREATE TABLE "SAPSync" (
    "DocEntry" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" TEXT NOT NULL,
    "DocNum" TEXT,
    "DocDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "SyncType" TEXT NOT NULL DEFAULT 'SAP',
    "SyncObject" TEXT,
    "Direction" TEXT NOT NULL DEFAULT 'POS to SAP',
    "OutletId" TEXT,
    "StartTime" TIMESTAMP(3),
    "EndTime" TIMESTAMP(3),
    "TotalRecords" INTEGER NOT NULL DEFAULT 0,
    "SuccessRecords" INTEGER NOT NULL DEFAULT 0,
    "FailedRecords" INTEGER NOT NULL DEFAULT 0,
    "PendingRecords" INTEGER NOT NULL DEFAULT 0,
    "ErrorMessage" TEXT,
    "RequestedBy" TEXT,
    "Status" TEXT NOT NULL DEFAULT 'Pending',
    "DocStatus" TEXT NOT NULL DEFAULT 'O',
    "Canceled" BOOLEAN NOT NULL DEFAULT false,
    "SapRef" TEXT,
    "SapSyncStatus" TEXT NOT NULL DEFAULT 'Pending',
    "SapSyncDate" TIMESTAMP(3),
    "CreateDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdateDate" TIMESTAMP(3) NOT NULL,
    "CreatedBy" TEXT,
    "UpdatedBy" TEXT,

    CONSTRAINT "SAPSync_pkey" PRIMARY KEY ("DocEntry")
);

CREATE TABLE "SAPSyncLine" (
    "DocEntry" INTEGER NOT NULL,
    "LineId" INTEGER NOT NULL,
    "ObjectType" TEXT,
    "ObjectKey" TEXT,
    "SapDocEntry" TEXT,
    "SyncStatus" TEXT,
    "ErrorMessage" TEXT,
    "SyncDate" TIMESTAMP(3),

    CONSTRAINT "SAPSyncLine_pkey" PRIMARY KEY ("DocEntry","LineId")
);

CREATE UNIQUE INDEX "SAPSync_TenantId_DocNum_key" ON "SAPSync"("TenantId", "DocNum");
CREATE INDEX "SAPSync_TenantId_DocDate_idx" ON "SAPSync"("TenantId", "DocDate");

ALTER TABLE "SAPSync" ADD CONSTRAINT "SAPSync_TenantId_fkey" FOREIGN KEY ("TenantId") REFERENCES "Tenant"("Id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SAPSync" ADD CONSTRAINT "SAPSync_OutletId_fkey" FOREIGN KEY ("OutletId") REFERENCES "Outlet"("Id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "SAPSyncLine" ADD CONSTRAINT "SAPSyncLine_DocEntry_fkey" FOREIGN KEY ("DocEntry") REFERENCES "SAPSync"("DocEntry") ON DELETE CASCADE ON UPDATE CASCADE;

CREATE TABLE "StockSync" (
    "DocEntry" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" TEXT NOT NULL,
    "DocNum" TEXT,
    "DocDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "SyncType" TEXT NOT NULL DEFAULT 'Stock',
    "SyncObject" TEXT,
    "Direction" TEXT NOT NULL DEFAULT 'POS to SAP',
    "OutletId" TEXT,
    "StartTime" TIMESTAMP(3),
    "EndTime" TIMESTAMP(3),
    "TotalRecords" INTEGER NOT NULL DEFAULT 0,
    "SuccessRecords" INTEGER NOT NULL DEFAULT 0,
    "FailedRecords" INTEGER NOT NULL DEFAULT 0,
    "PendingRecords" INTEGER NOT NULL DEFAULT 0,
    "ErrorMessage" TEXT,
    "RequestedBy" TEXT,
    "Status" TEXT NOT NULL DEFAULT 'Pending',
    "DocStatus" TEXT NOT NULL DEFAULT 'O',
    "Canceled" BOOLEAN NOT NULL DEFAULT false,
    "SapRef" TEXT,
    "SapSyncStatus" TEXT NOT NULL DEFAULT 'Pending',
    "SapSyncDate" TIMESTAMP(3),
    "CreateDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdateDate" TIMESTAMP(3) NOT NULL,
    "CreatedBy" TEXT,
    "UpdatedBy" TEXT,

    CONSTRAINT "StockSync_pkey" PRIMARY KEY ("DocEntry")
);

CREATE TABLE "StockSyncLine" (
    "DocEntry" INTEGER NOT NULL,
    "LineId" INTEGER NOT NULL,
    "ObjectType" TEXT,
    "ObjectKey" TEXT,
    "SapDocEntry" TEXT,
    "SyncStatus" TEXT,
    "ErrorMessage" TEXT,
    "SyncDate" TIMESTAMP(3),

    CONSTRAINT "StockSyncLine_pkey" PRIMARY KEY ("DocEntry","LineId")
);

CREATE UNIQUE INDEX "StockSync_TenantId_DocNum_key" ON "StockSync"("TenantId", "DocNum");
CREATE INDEX "StockSync_TenantId_DocDate_idx" ON "StockSync"("TenantId", "DocDate");

ALTER TABLE "StockSync" ADD CONSTRAINT "StockSync_TenantId_fkey" FOREIGN KEY ("TenantId") REFERENCES "Tenant"("Id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "StockSync" ADD CONSTRAINT "StockSync_OutletId_fkey" FOREIGN KEY ("OutletId") REFERENCES "Outlet"("Id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "StockSyncLine" ADD CONSTRAINT "StockSyncLine_DocEntry_fkey" FOREIGN KEY ("DocEntry") REFERENCES "StockSync"("DocEntry") ON DELETE CASCADE ON UPDATE CASCADE;

